	memset(z0,0,sizeof(z0));
	mainFFT(x0,y0,z0);
	memset(z1,0,sizeof(z1));
	mainFFT(x1,y0,z1);
	mainFFT(x0,y1,z1);
	memset(z2,0,sizeof(z2));
	mainFFT(x1,y1,z2);
	memset(z,0,sizeof(z));
	for (int i=0;i<=n;i++)
		z[i]=(1LL*q*q*z2[i]+1LL*q*z1[i]+z0[i])%p;
	for (int i=0;i<=n;i++)
		f[b[m]][i]=1LL*z[i]*fac[i]%p;
	return;
}

int main()
{
	scanf("%I64d%d",&m,&n);
	if (m>n)
		return printf("0"),0;
	preC();
	preFFT();
	h[0]=1;
	for (i=1;i<=n;i++)
		h[i]=(h[i-1]+h[i-1])%p;
	solve(m);
	for (i=m;i<=n;i++)
		s=(s+1LL*f[b[m]][i]*C(n,i))%p;
	printf("%d",s);
	return 0;
}
